/* Opened straight from disk (file://) the browser refuses to fetch font files, so the page would fall back to a system
   monospace. This shim, loaded only on file://, hands the same Cascadia Code faces to the page from inside a script. */
(function(){if(!window.FontFace||!document.fonts)return;
var L=[{u:"U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD",d:""},{u:"U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF",d:""},{u:"U+2000-2001, U+2004-2008, U+200A, U+23B8-23BD, U+2500-259F",d:""}];
L.forEach(function(f){try{var s=atob(f.d),a=new Uint8Array(s.length);for(var i=0;i<s.length;i++)a[i]=s.charCodeAt(i);
var ff=new FontFace("Cascadia Code",a.buffer,{weight:"200 700",style:"normal",unicodeRange:f.u,display:"block"});document.fonts.add(ff);ff.load()}catch(e){}});
})();
